// Owner: S4 · Familial Risk & Clinical Approval — W.M.S.S.B. Wasala (IT24100559)
// Ownership is binding — do not edit this file if it is not yours. docs/OWNERSHIP.tsv
import { useCallback, useEffect, useMemo, useState } from 'react'

import { EmptyState, ErrorState, LoadingState } from '../../components/shared/ViewState'
import { StatusBadge } from '../../components/shared/StatusBadge'
import { apiClient, type DoctorDto, type PagedResult } from '../../services/apiClient'

type FilterStatus = 'ALL' | 'PENDING' | 'VERIFIED' | 'MORE_INFO' | 'REJECTED' | 'SUSPENDED'

export function DoctorVerificationPage() {
  const [doctors, setDoctors] = useState<DoctorDto[]>([])
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading')
  const [message, setMessage] = useState('')
  const [generatedTokenInfo, setGeneratedTokenInfo] = useState<{ doctorReg: string; token: string } | null>(null)
  const [activeFilter, setActiveFilter] = useState<FilterStatus>('ALL')
  const [search, setSearch] = useState('')
  const [selectedDoctor, setSelectedDoctor] = useState<DoctorDto | null>(null)
  const [doctorToDelete, setDoctorToDelete] = useState<DoctorDto | null>(null)
  const [isDeleting, setIsDeleting] = useState(false)

  const load = useCallback(async () => {
    setStatus('loading')
    try {
      const response = await apiClient.get<PagedResult<DoctorDto>>('/admin/doctors', {
        params: { page: 1, pageSize: 100 },
      })
      setDoctors(response.data.items)
      setStatus('ready')
    } catch {
      setStatus('error')
    }
  }, [])

  useEffect(() => {
    void load()
  }, [load])

  async function handleResetPassword(userId: string, regNumberDisplay: string) {
    try {
      const response = await apiClient.post<{ success: boolean; message: string; resetToken?: string }>(
        `/auth/admin/users/${userId}/reset-password`,
        { reason: 'Administrative password reset' }
      )
      setMessage(`Password reset token generated for Doctor (${regNumberDisplay}) and logged to audit trail.`)
      if (response.data.resetToken) {
        setGeneratedTokenInfo({ doctorReg: regNumberDisplay, token: response.data.resetToken })
      }
    } catch {
      setMessage('Failed to generate password reset token.')
    }
  }

  async function decide(id: string, action: 'verify' | 'request-info' | 'reject' | 'suspend') {
    const actionLabels: Record<string, string> = {
      verify: 'Administrative verification completed',
      'request-info': 'Additional registration details requested',
      reject: 'Doctor registration rejected',
      suspend: 'Doctor account suspended',
    }
    try {
      await apiClient.post(`/admin/doctors/${id}/${action}`, {
        reason: actionLabels[action] ?? 'Administrative verification update',
      })
      setMessage('Verification status updated and audited.')
      await load()
    } catch {
      setMessage('Verification status could not be updated.')
    }
  }

  async function confirmDeleteDoctor() {
    if (!doctorToDelete) return
    setIsDeleting(true)
    try {
      // Accounts are deactivated, never deleted: approvals, grants and audit history must survive.
      await apiClient.post(`/auth/admin/users/${doctorToDelete.userId}/toggle-status`, { isActive: false, reason: 'Deactivated by admin' })
      setMessage(`Doctor account "${doctorToDelete.displayName || doctorToDelete.email}" deactivated. History is kept.`)
      await load()
      setDoctorToDelete(null)
      if (selectedDoctor?.id === doctorToDelete.id) {
        setSelectedDoctor(null)
      }
    } catch {
      setMessage('Failed to deactivate doctor account.')
    } finally {
      setIsDeleting(false)
    }
  }

  const filteredDoctors = useMemo(() => {
    return doctors.filter((doc) => {
      const q = search.toLowerCase().trim()
      const matchesSearch =
        q === '' ||
        (doc.displayName && doc.displayName.toLowerCase().includes(q)) ||
        (doc.email && doc.email.toLowerCase().includes(q)) ||
        (doc.specialty && doc.specialty.toLowerCase().includes(q)) ||
        (doc.hospitalClinic && doc.hospitalClinic.toLowerCase().includes(q)) ||
        (doc.registrationNumber && doc.registrationNumber.toLowerCase().includes(q)) ||
        doc.registrationNumberLastFour.toLowerCase().includes(q) ||
        (doc.phoneNumber && doc.phoneNumber.toLowerCase().includes(q))

      if (!matchesSearch) return false

      const s = doc.verificationStatus?.toUpperCase() ?? 'PENDING'
      switch (activeFilter) {
        case 'PENDING':
          return s === 'PENDING'
        case 'VERIFIED':
          return s === 'VERIFIED'
        case 'MORE_INFO':
          return s === 'MOREINFORMATIONREQUIRED' || s === 'MORE_INFORMATION_REQUIRED'
        case 'REJECTED':
          return s === 'REJECTED'
        case 'SUSPENDED':
          return s === 'SUSPENDED'
        default:
          return true
      }
    })
  }, [doctors, search, activeFilter])

  const pendingCount = doctors.filter((d) => (d.verificationStatus?.toUpperCase() ?? 'PENDING') === 'PENDING').length
  const verifiedCount = doctors.filter((d) => d.verificationStatus?.toUpperCase() === 'VERIFIED').length
  const moreInfoCount = doctors.filter((d) => {
    const s = d.verificationStatus?.toUpperCase()
    return s === 'MOREINFORMATIONREQUIRED' || s === 'MORE_INFORMATION_REQUIRED'
  }).length
  const suspendedCount = doctors.filter((d) => d.verificationStatus?.toUpperCase() === 'SUSPENDED').length
  const rejectedCount = doctors.filter((d) => d.verificationStatus?.toUpperCase() === 'REJECTED').length

  return (
    <div className="page-stack">
      <header className="page-header">
        <div>
          <p className="eyebrow">Clinic administration</p>
          <h1>Doctor verification</h1>
          <p>Manual administrative verification and registry of clinic doctors.</p>
        </div>
      </header>

      {message && <p role="status" className="status-banner">{message}</p>}

      {generatedTokenInfo && (
        <div className="panel" style={{ borderLeft: '4px solid var(--primary)', backgroundColor: 'rgba(16, 185, 129, 0.08)', marginBottom: '16px' }}>
          <h3>🔑 One-Time Reset Token Generated</h3>
          <p>
            Secure reset token for Doctor <strong>{generatedTokenInfo.doctorReg}</strong>:{' '}
            <strong style={{ fontFamily: 'monospace', fontSize: '1.1rem', color: 'var(--primary)', letterSpacing: '1px' }}>
              {generatedTokenInfo.token}
            </strong>
          </p>
          <p className="muted" style={{ fontSize: '0.85rem' }}>
            This token is valid for 30 minutes and has been logged to the audit trail.
          </p>
          <button type="button" className="button button--secondary button--sm" onClick={() => setGeneratedTokenInfo(null)}>
            Dismiss
          </button>
        </div>
      )}

      {/* Clinician Review & Details Modal */}
      {selectedDoctor && (
        <div
          role="dialog"
          aria-modal="true"
          aria-labelledby="doctor-details-title"
          style={{
            position: 'fixed',
            inset: 0,
            backgroundColor: 'rgba(0, 0, 0, 0.65)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 10000,
            padding: '16px',
            backdropFilter: 'blur(4px)',
          }}
          onClick={() => setSelectedDoctor(null)}
        >
          <div
            className="panel"
            style={{
              width: '100%',
              maxWidth: '560px',
              backgroundColor: 'var(--surface)',
              borderRadius: 'var(--r-lg, 18px)',
              padding: '24px',
              border: '1px solid var(--border)',
              boxShadow: '0 20px 40px rgba(0,0,0,0.4)',
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px', borderBottom: '1px solid var(--border-subtle)', paddingBottom: '12px' }}>
              <div>
                <span className="eyebrow" style={{ fontSize: '0.75rem' }}>Clinician Profile Details</span>
                <h3 id="doctor-details-title" style={{ margin: 0, fontSize: '1.25rem' }}>
                  {selectedDoctor.displayName || 'Doctor Application'}
                </h3>
              </div>
              <button
                type="button"
                className="button button--secondary button--sm"
                onClick={() => setSelectedDoctor(null)}
                style={{ padding: '4px 10px' }}
              >
                ✕ Close
              </button>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '14px', marginBottom: '20px' }}>
              <div style={{ background: 'var(--surface-subtle)', padding: '10px 14px', borderRadius: 'var(--r-sm, 10px)' }}>
                <div className="muted" style={{ fontSize: '0.75rem', fontWeight: 600, textTransform: 'uppercase' }}>Full Name</div>
                <div style={{ fontWeight: 600, marginTop: '2px' }}>{selectedDoctor.displayName || '—'}</div>
              </div>

              <div style={{ background: 'var(--surface-subtle)', padding: '10px 14px', borderRadius: 'var(--r-sm, 10px)' }}>
                <div className="muted" style={{ fontSize: '0.75rem', fontWeight: 600, textTransform: 'uppercase' }}>Email Address</div>
                <div style={{ fontWeight: 600, marginTop: '2px', wordBreak: 'break-all' }}>{selectedDoctor.email || '—'}</div>
              </div>

              <div style={{ background: 'var(--surface-subtle)', padding: '10px 14px', borderRadius: 'var(--r-sm, 10px)' }}>
                <div className="muted" style={{ fontSize: '0.75rem', fontWeight: 600, textTransform: 'uppercase' }}>Medical Reg No.</div>
                <div style={{ fontWeight: 600, marginTop: '2px', fontFamily: 'monospace' }}>
                  {selectedDoctor.registrationNumber || `••••${selectedDoctor.registrationNumberLastFour}`}
                </div>
              </div>

              <div style={{ background: 'var(--surface-subtle)', padding: '10px 14px', borderRadius: 'var(--r-sm, 10px)' }}>
                <div className="muted" style={{ fontSize: '0.75rem', fontWeight: 600, textTransform: 'uppercase' }}>Specialization</div>
                <div style={{ fontWeight: 600, marginTop: '2px' }}>{selectedDoctor.specialty || 'General Practice'}</div>
              </div>

              <div style={{ background: 'var(--surface-subtle)', padding: '10px 14px', borderRadius: 'var(--r-sm, 10px)', gridColumn: 'span 2' }}>
                <div className="muted" style={{ fontSize: '0.75rem', fontWeight: 600, textTransform: 'uppercase' }}>Hospital / Clinic</div>
                <div style={{ fontWeight: 600, marginTop: '2px' }}>{selectedDoctor.hospitalClinic || '—'}</div>
              </div>

              <div style={{ background: 'var(--surface-subtle)', padding: '10px 14px', borderRadius: 'var(--r-sm, 10px)' }}>
                <div className="muted" style={{ fontSize: '0.75rem', fontWeight: 600, textTransform: 'uppercase' }}>Phone Number</div>
                <div style={{ fontWeight: 600, marginTop: '2px' }}>{selectedDoctor.phoneNumber || '—'}</div>
              </div>

              <div style={{ background: 'var(--surface-subtle)', padding: '10px 14px', borderRadius: 'var(--r-sm, 10px)' }}>
                <div className="muted" style={{ fontSize: '0.75rem', fontWeight: 600, textTransform: 'uppercase' }}>Status</div>
                <div style={{ marginTop: '2px' }}><StatusBadge status={selectedDoctor.verificationStatus} /></div>
              </div>
            </div>

            <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', justifyContent: 'flex-end', alignItems: 'center', borderTop: '1px solid var(--border-subtle)', paddingTop: '16px' }}>
              <button
                type="button"
                className="button button--danger button--sm"
                onClick={() => {
                  const doc = selectedDoctor
                  setSelectedDoctor(null)
                  setDoctorToDelete(doc)
                }}
                style={{ marginRight: 'auto', backgroundColor: 'rgba(239, 68, 68, 0.12)', color: '#ef4444', borderColor: 'rgba(239, 68, 68, 0.3)' }}
              >
                Deactivate Doctor
              </button>

              {selectedDoctor.verificationStatus !== 'Verified' && (
                <button
                  type="button"
                  className="button button--primary button--sm"
                  onClick={async () => {
                    await decide(selectedDoctor.id, 'verify')
                    setSelectedDoctor(null)
                  }}
                >
                  ✓ Verify Doctor
                </button>
              )}
              {selectedDoctor.verificationStatus === 'Verified' && (
                <button
                  type="button"
                  className="button button--danger button--sm"
                  onClick={async () => {
                    await decide(selectedDoctor.id, 'suspend')
                    setSelectedDoctor(null)
                  }}
                >
                  Suspend Account
                </button>
              )}
              <button
                type="button"
                className="button button--secondary button--sm"
                onClick={async () => {
                  await decide(selectedDoctor.id, 'request-info')
                  setSelectedDoctor(null)
                }}
              >
                Request info
              </button>
              {selectedDoctor.verificationStatus !== 'Rejected' && (
                <button
                  type="button"
                  className="button button--danger button--sm"
                  onClick={async () => {
                    await decide(selectedDoctor.id, 'reject')
                    setSelectedDoctor(null)
                  }}
                >
                  Reject
                </button>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {doctorToDelete && (
        <div
          role="dialog"
          aria-modal="true"
          aria-labelledby="delete-dialog-title"
          style={{
            position: 'fixed',
            inset: 0,
            backgroundColor: 'rgba(0, 0, 0, 0.65)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 10001,
            padding: '16px',
            backdropFilter: 'blur(4px)',
          }}
          onClick={() => !isDeleting && setDoctorToDelete(null)}
        >
          <div
            className="panel"
            style={{
              width: '100%',
              maxWidth: '440px',
              backgroundColor: 'var(--surface)',
              borderRadius: 'var(--r-lg, 18px)',
              padding: '24px',
              border: '1px solid var(--border)',
              boxShadow: '0 20px 40px rgba(0,0,0,0.4)',
            }}
            onClick={(e) => e.stopPropagation()}
          >
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '16px' }}>
              <div style={{ fontSize: '2rem' }}>⚠️</div>
              <div>
                <h3 id="delete-dialog-title" style={{ margin: 0, fontSize: '1.2rem', color: '#ef4444' }}>
                  Deactivate Doctor Account
                </h3>
                <p className="muted" style={{ margin: 0, fontSize: '0.85rem' }}>This action cannot be undone.</p>
              </div>
            </div>

            <p style={{ fontSize: '0.95rem', marginBottom: '20px', lineHeight: 1.5 }}>
              Deactivate doctor{' '}
              <strong>{doctorToDelete.displayName || doctorToDelete.email}</strong> (
              <span style={{ fontFamily: 'monospace', fontWeight: 600 }}>
                {doctorToDelete.registrationNumber || `••••${doctorToDelete.registrationNumberLastFour}`}
              </span>
              )? They can no longer sign in. Approvals, grants and audit history are kept, and the account can be reactivated.
            </p>

            <div style={{ display: 'flex', gap: '10px', justifyContent: 'flex-end' }}>
              <button
                type="button"
                className="button button--secondary button--sm"
                onClick={() => setDoctorToDelete(null)}
                disabled={isDeleting}
              >
                Cancel
              </button>
              <button
                type="button"
                className="button button--danger button--sm"
                onClick={() => void confirmDeleteDoctor()}
                disabled={isDeleting}
                style={{ backgroundColor: '#dc2626', borderColor: '#dc2626' }}
              >
                {isDeleting ? 'Deactivating...' : 'Deactivate'}
              </button>
            </div>
          </div>
        </div>
      )}

      <section className="panel">
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '12px', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
          <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap' }}>
            <button
              type="button"
              className={`button button--sm ${activeFilter === 'ALL' ? 'button--primary' : 'button--secondary'}`}
              onClick={() => setActiveFilter('ALL')}
            >
              All ({doctors.length})
            </button>
            <button
              type="button"
              className={`button button--sm ${activeFilter === 'PENDING' ? 'button--primary' : 'button--secondary'}`}
              onClick={() => setActiveFilter('PENDING')}
            >
              Pending ({pendingCount})
            </button>
            <button
              type="button"
              className={`button button--sm ${activeFilter === 'VERIFIED' ? 'button--primary' : 'button--secondary'}`}
              onClick={() => setActiveFilter('VERIFIED')}
            >
              Verified ({verifiedCount})
            </button>
            <button
              type="button"
              className={`button button--sm ${activeFilter === 'MORE_INFO' ? 'button--primary' : 'button--secondary'}`}
              onClick={() => setActiveFilter('MORE_INFO')}
            >
              More info ({moreInfoCount})
            </button>
            <button
              type="button"
              className={`button button--sm ${activeFilter === 'SUSPENDED' ? 'button--primary' : 'button--secondary'}`}
              onClick={() => setActiveFilter('SUSPENDED')}
            >
              Suspended ({suspendedCount})
            </button>
            <button
              type="button"
              className={`button button--sm ${activeFilter === 'REJECTED' ? 'button--primary' : 'button--secondary'}`}
              onClick={() => setActiveFilter('REJECTED')}
            >
              Rejected ({rejectedCount})
            </button>
          </div>

          <div style={{ minWidth: '260px' }}>
            <input
              type="search"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search doctor, hospital, reg no..."
              aria-label="Search doctors"
              style={{
                width: '100%',
                padding: '6px 12px',
                borderRadius: 'var(--r-md, 14px)',
                border: '1px solid var(--border)',
                background: 'var(--surface)',
                color: 'var(--text)',
                fontSize: '0.88rem',
              }}
            />
          </div>
        </div>

        {status === 'loading' ? (
          <LoadingState label="Loading doctor queue" />
        ) : status === 'error' ? (
          <ErrorState message="Doctor queue could not be loaded." onRetry={() => void load()} />
        ) : filteredDoctors.length === 0 ? (
          <EmptyState
            title={activeFilter === 'ALL' ? 'No doctors registered' : `No ${activeFilter.toLowerCase()} doctors`}
            message="New clinician registrations and status updates appear here."
          />
        ) : (
          <div className="table-scroll">
            <table>
              <thead>
                <tr>
                  <th>Doctor</th>
                  <th>Medical Reg No.</th>
                  <th>Specialization</th>
                  <th>Hospital / Clinic</th>
                  <th>Phone Number</th>
                  <th>Status</th>
                  <th style={{ minWidth: '220px' }}>Actions</th>
                </tr>
              </thead>
              <tbody>
                {filteredDoctors.map((doctor) => {
                  const regDisplay = doctor.registrationNumber || `••••${doctor.registrationNumberLastFour}`
                  const statusNorm = doctor.verificationStatus?.toLowerCase() ?? 'pending'
                  const isVerified = statusNorm === 'verified'
                  const isPending = statusNorm === 'pending'
                  const isMoreInfo = statusNorm === 'moreinformationrequired' || statusNorm === 'more_information_required'

                  return (
                    <tr key={doctor.id}>
                      <td>
                        <div>
                          <strong>{doctor.displayName || 'Doctor Account'}</strong>
                          {doctor.email && <div className="muted" style={{ fontSize: '0.8rem' }}>{doctor.email}</div>}
                        </div>
                      </td>
                      <td>
                        <span style={{ fontFamily: 'monospace', fontWeight: 600 }}>{regDisplay}</span>
                      </td>
                      <td>{doctor.specialty ?? 'General Practice'}</td>
                      <td>{doctor.hospitalClinic ?? '—'}</td>
                      <td>{doctor.phoneNumber ?? '—'}</td>
                      <td>
                        <StatusBadge status={doctor.verificationStatus} />
                      </td>
                      <td>
                        <div className="table-actions" style={{ display: 'flex', gap: '6px', flexWrap: 'nowrap' }}>
                          <button
                            className="button button--secondary button--sm"
                            onClick={() => setSelectedDoctor(doctor)}
                            title="Show full registration details"
                            style={{ padding: '4px 8px' }}
                          >
                            👁️ Details
                          </button>

                          {isPending && (
                            <>
                              <button
                                className="button button--primary button--sm"
                                onClick={() => void decide(doctor.id, 'verify')}
                                style={{ padding: '4px 8px' }}
                              >
                                Verify
                              </button>
                              <button
                                className="button button--danger button--sm"
                                onClick={() => void decide(doctor.id, 'reject')}
                                style={{ padding: '4px 8px' }}
                              >
                                Reject
                              </button>
                            </>
                          )}

                          {isVerified && (
                            <button
                              className="button button--danger button--sm"
                              onClick={() => void decide(doctor.id, 'suspend')}
                              title="Suspend doctor verification"
                              style={{ padding: '4px 8px' }}
                            >
                              Suspend
                            </button>
                          )}

                          {isMoreInfo && (
                            <button
                              className="button button--primary button--sm"
                              onClick={() => void decide(doctor.id, 'verify')}
                              style={{ padding: '4px 8px' }}
                            >
                              Verify
                            </button>
                          )}

                          {(!isPending && !isVerified && !isMoreInfo) && (
                            <button
                              className="button button--primary button--sm"
                              onClick={() => void decide(doctor.id, 'verify')}
                              title="Re-verify doctor"
                              style={{ padding: '4px 8px' }}
                            >
                              Re-verify
                            </button>
                          )}

                          <button
                            className="button button--secondary button--sm"
                            onClick={() => void handleResetPassword(doctor.userId, regDisplay)}
                            title="Generate one-time password reset token"
                            style={{ padding: '4px 8px' }}
                          >
                            🔑
                          </button>

                          <button
                            className="button button--danger button--sm"
                            onClick={() => setDoctorToDelete(doctor)}
                            title="Deactivate doctor account"
                            style={{ padding: '4px 8px', backgroundColor: 'rgba(239, 68, 68, 0.12)', color: '#ef4444', borderColor: 'rgba(239, 68, 68, 0.3)' }}
                          >
                            ⏸
                          </button>
                        </div>
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </div>
  )
}
